const fs = require('fs');
const path = require('path');
const event = $input.first().json;
const body = event.body ?? event;
const required = ['title', 'document_url', 'report_date', 'idempotency_key'];
for (const field of required) {
  if (typeof body[field] !== 'string' || !body[field].trim()) {
    throw new Error(`Missing or invalid field: ${field}`);
  }
}
const title = body.title.trim();
const documentUrl = body.document_url.trim();
const reportDate = body.report_date.trim();
const idempotencyKey = body.idempotency_key.trim();
if (title.length > 120 || idempotencyKey.length > 180) {
  throw new Error('Title or idempotency key is too long');
}
if (!/^\d{4}-\d{2}-\d{2}$/.test(reportDate)) {
  throw new Error('report_date must use YYYY-MM-DD');
}
if (!/^https:\/\/alidocs\.dingtalk\.com\//.test(documentUrl)) {
  throw new Error('document_url must be an alidocs.dingtalk.com HTTPS URL');
}
if (!/^[A-Za-z0-9:._-]+$/.test(idempotencyKey)) {
  throw new Error('idempotency_key contains unsupported characters');
}
const storeDir = '/home/node/.n8n/delivery-state';
fs.mkdirSync(storeDir, { recursive: true });
const recordPath = path.join(storeDir, `${idempotencyKey}.json`);
let existing = null;
try {
  existing = JSON.parse(fs.readFileSync(recordPath, 'utf8'));
} catch (error) {
  if (error.code !== 'ENOENT') throw error;
}
let claimed = false;
if (!existing) {
  const pending = { status: 'pending', idempotency_key: idempotencyKey, report_date: reportDate, claimed_at: new Date().toISOString() };
  try {
    fs.writeFileSync(recordPath, JSON.stringify(pending) + '\n', { flag: 'wx', mode: 0o600 });
    existing = pending;
    claimed = true;
  } catch (error) {
    if (error.code !== 'EEXIST') throw error;
    existing = JSON.parse(fs.readFileSync(recordPath, 'utf8'));
  }
}
return [{
  json: {
    title,
    document_url: documentUrl,
    report_date: reportDate,
    idempotency_key: idempotencyKey,
    record_path: recordPath,
    duplicate: !claimed && existing.status === 'sent',
    pending: !claimed && existing.status !== 'sent',
    existing,
    dingtalk_payload: {
      msgtype: 'markdown',
      markdown: {
        title,
        text: `### ${title}\n\n[点击查看完整市场情报](${documentUrl})`,
      },
    },
  },
}];

const fs = require('fs');
const response = $input.first().json;
if (Number(response.errcode) !== 0) {
  throw new Error(`DingTalk failed: ${response.errmsg ?? 'unknown error'}`);
}
const validated = $('Validate Request').first().json;
const sent = {
  status: 'sent',
  idempotency_key: validated.idempotency_key,
  report_date: validated.report_date,
  document_url: validated.document_url,
  sent_at: new Date().toISOString(),
};
fs.writeFileSync(validated.record_path, JSON.stringify(sent) + '\n', { mode: 0o600 });
return [{
  json: {
    ok: true,
    duplicate: false,
    idempotency_key: validated.idempotency_key,
    errcode: Number(response.errcode),
    errmsg: response.errmsg ?? 'ok',
    sent_at: sent.sent_at,
  },
}];
